-- ─────────────────────────────────────────────────────────────────────────────
-- The Dojo: Content Seed — Fake Tasting Notes & Sensei Quotes
--
-- Populates:
--   • duel_fake_notes — 300+ funny fake notes across three difficulty tiers
--   • sensei_quotes — 90+ sardonic quotes across six outcome keys
--
-- Idempotent: skips insert if rows already exist (count guard).
-- ─────────────────────────────────────────────────────────────────────────────

-- ─────────────────────────────────────────────────────────────────────────────
-- 1. duel_fake_notes
--
-- Tier 1: obviously wrong, absurdist humor
-- Tier 2: plausible-sounding but wrong
-- Tier 3: convincingly close to real tasting language, subtly off
-- ─────────────────────────────────────────────────────────────────────────────

do $$ begin
  if (select count(*) from public.duel_fake_notes) = 0 then

    insert into public.duel_fake_notes (note, difficulty_tier) values

    -- ── TIER 1 — Obviously wrong, absurdist humor ─────────────────────────
    ('On the nose: a 2009 Honda Civic, three parking tickets, and the faint hope that things will be different this time. Palate: wet cardboard, existential dread, and a gas station slushy. Finish: surprisingly long; like a commute you didn''t plan for.', 1),
